import preloads from "./font-preloads.json";

/**
 * Manrope and DM Mono, self-hosted (public/assets/css/fonts.css, generated by
 * scripts/fonts/build-fonts.py). The Latin files are preloaded on every page:
 * they arrive with the HTML instead of after the stylesheet, and together with
 * font-display: optional the first paint already uses them and text never
 * swaps font afterwards.
 */
export const FONT_PRELOADS: readonly string[] = preloads;

const PRELOAD_TAGS = FONT_PRELOADS.map((href) => `<link rel="preload" href="${href}" as="font" type="font/woff2" crossorigin>`).join("");

/** Adds the preloads to a hand-written HTML document, right before its fonts.css link. */
export function withFontPreloads(html: string): string {
  return html.replace(/<link rel="stylesheet" href="\/assets\/css\/fonts\.css"\s*\/?>/, (link) => `${PRELOAD_TAGS}${link}`);
}
